const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const laBounds = ee.Geometry.Rectangle([-118.7, 33.7, -117.9, 34.3]); // Los Angeles area

  // Define date ranges for comparison
  const dates = {
    '2018': ['2018-10-01', '2018-10-23'],
    '2019': ['2019-10-01', '2019-10-23'], 
    '2021': ['2021-10-01', '2021-10-23']
  };

  // 2. Data Acquisition & Processing
  const results = {};

  for (const [year, dateRange] of Object.entries(dates)) {
    // Get TROPOMI NO2 data with quality filtering
    let collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
      .select('NO2_column_number_density')
      .filterDate(dateRange[0], dateRange[1])
      .filterBounds(laBounds);

    const size = collection.size().getInfo();
    console.log(`${year} Images: ${size}`);

    if (size === 0) {
      console.log(`No data for ${year}`);
      console.log("<answer>C1</answer>");
      return;
    }

    // Create mean composite and mask low quality
    const meanImg = collection.mean();

    // Check valid pixels
    const countStats = meanImg.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: laBounds,
      scale: 1000,
      maxPixels: 1e9
    });

    const pixelCount = countStats.get('NO2_column_number_density').getInfo();
    console.log(`${year} Valid Pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      console.log(`No valid pixels for ${year}`);
      console.log("<answer>C2</answer>");
      return;
    }

    // Calculate mean NO2 concentration
    const meanStats = meanImg.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: laBounds,
      scale: 1000,
      maxPixels: 1e9
    });

    const meanNO2 = meanStats.get('NO2_column_number_density').getInfo();
    console.log(`${year} Mean NO2: ${meanNO2 ? meanNO2.toFixed(6) : 'null'}`);

    if (meanNO2 === null || meanNO2 === undefined || !isFinite(meanNO2)) {
      console.log(`Invalid calculation for ${year}`);
      console.log("<answer>C3</answer>");
      return;
    }

    results[year] = meanNO2;
  }

  // 3. Comparison Logic
  console.log(`Comparison: 2021 (${results['2021'].toFixed(6)}) vs 2019 (${results['2019'].toFixed(6)}) vs 2018 (${results['2018'].toFixed(6)})`);

  // Check if 2021 is lower than both 2019 and 2018
  const isLowerThan2019 = results['2021'] < results['2019'];
  const isLowerThan2018 = results['2021'] < results['2018'];

  if (isLowerThan2019 && isLowerThan2018) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
